using namespace std;

using int64 = long long;
using i128 = __int128_t;

struct SequenceInfo {
    int64 first;
    int64 period;
    bool periodic;
    bool found;
};

int64 modNext(int64 value, int64 x, int64 y, int64 m) {
    return static_cast<int64>(((i128)value * x + y) % m);
}

SequenceInfo analyze(int64 h, int64 target, int64 x, int64 y, int64 m) {
    auto next = [&](int64 value) {
        return modNext(value, x, y, m);
    };

    int64 slow = next(h);
    int64 fast = next(next(h));

    while (slow != fast) {
        slow = next(slow);
        fast = next(next(fast));
    }

    int64 mu = 0;
    slow = h;
    while (slow != fast) {
        slow = next(slow);
        fast = next(fast);
        ++mu;
    }

    int64 period = 1;
    fast = next(slow);
    while (slow != fast) {
        fast = next(fast);
        ++period;
    }

    int64 value = h;
    for (int64 t = 0; t < mu + period; ++t) {
        if (value == target) {
            return {t, period, t >= mu, true};
        }
        value = next(value);
    }

    return {-1, period, false, false};
}

int64 extendedGcd(int64 a, int64 b, int64& x, int64& y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }

    int64 x1, y1;
    int64 g = extendedGcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}

i128 normalize(i128 value, i128 mod) {
    value %= mod;
    if (value < 0) value += mod;
    return value;
}

void printInt128(i128 value) {
    if (value == 0) {
        cout << '0';
        return;
    }

    if (value < 0) {
        cout << '-';
        value = -value;
    }

    string result;
    while (value > 0) {
        result.push_back(char('0' + value % 10));
        value /= 10;
    }
    reverse(result.begin(), result.end());
    cout << result;
}

