    int64 h1, a1, x1, y1;
    int64 h2, a2, x2, y2;

    cin >> m;
    cin >> h1 >> a1;
    cin >> x1 >> y1;
    cin >> h2 >> a2;
    cin >> x2 >> y2;

    SequenceInfo s1 = analyze(h1, a1, x1, y1, m);
    SequenceInfo s2 = analyze(h2, a2, x2, y2, m);

    if (!s1.found || !s2.found) {
        cout << -1 << '\n';
        return 0;
    }

    if (!s1.periodic && !s2.periodic) {
        cout << (s1.first == s2.first ? s1.first : -1) << '\n';
        return 0;
    }

    if (!s1.periodic) {
        if (s1.first >= s2.first &&
            (s1.first - s2.first) % s2.period == 0) {
            cout << s1.first << '\n';
        } else {
            cout << -1 << '\n';
        }
        return 0;
